import { Injectable, computed, inject, signal } from '@angular/core';
import type { BadgeVariants } from '@spartan-ng/helm/badge';
import { MemberService } from '../member/member.service';
import type { MemberFormModel } from '../member/member.schema';

type BadgeVariant = NonNullable<BadgeVariants['variant']>;

/** Every piece of spec text the screen shows. The template binds to these and never repeats them. */
const MEMBERS_TEXT = {
  title: 'Members',
  plural: 'members',
  createLabel: 'Register member',
  createTitle: 'Create member',
  createDescription: 'Add a new member.',
  editTitle: 'Edit member',
  editDescription: "Change this member's details and save.",
  deleteTitle: 'Delete member?',
  deleteDescription: 'This member will be permanently removed. This cannot be undone.',
  searchLabel: 'Search members',
  searchPlaceholder: 'Search members...',
  empty: 'No members match this filter.',
  edit: 'Edit',
  delete: 'Delete',
  actions: 'Actions',
  filters: {
    standing: 'Blocked only',
  },
  columns: {
    name: 'Full Name',
    tier: 'Membership Tier',
    standing: 'Account Standing',
    status: 'Status',
    city: 'City',
  },
} as const;

const STANDING_VARIANTS: Readonly<Record<string, BadgeVariant>> = {
  Blocked: 'destructive',
  Restricted: 'default',
};

const STATUS_VARIANTS: Readonly<Record<string, BadgeVariant>> = {
  Active: 'default',
  Suspended: 'secondary',
};

@Injectable()
export class MembersViewModel {
  private readonly memberService = inject(MemberService);

  readonly text = MEMBERS_TEXT;
  readonly members = this.memberService.members;

  readonly searchQuery = signal('');
  readonly standingFilterOn = signal(false);

  /** The id of the member being edited, '' for a new one, or null when closed. */
  readonly editing = signal<string | null>(null);

  readonly filtered = computed(() => {
    const q = this.searchQuery().toLowerCase();
    const standingOn = this.standingFilterOn();
    const rows = this.members()
      .filter((item) => !standingOn || item.standing === 'Blocked')
      .filter(
        (item) => !q || item.name.toLowerCase().includes(q) || item.city.toLowerCase().includes(q),
      );
    return rows;
  });

  readonly editingMember = computed(() => {
    const id = this.editing();
    return id ? this.memberService.byId(id) : undefined;
  });

  readonly standingVariant = (value: string): BadgeVariant =>
    STANDING_VARIANTS[value] ?? 'secondary';

  readonly statusVariant = (value: string): BadgeVariant => STATUS_VARIANTS[value] ?? 'outline';

  toggleStandingFilter(): void {
    this.standingFilterOn.update((on) => !on);
  }

  startCreate(): void {
    this.editing.set('');
  }

  startEdit(id: string): void {
    this.editing.set(id);
  }

  cancel(): void {
    this.editing.set(null);
  }

  save(model: MemberFormModel): void {
    const id = this.editing();
    if (id) {
      this.memberService.update(id, model);
    } else {
      this.memberService.create(model);
    }
    this.editing.set(null);
  }

  remove(id: string): void {
    this.memberService.remove(id);
    if (this.editing() === id) this.editing.set(null);
  }
}
